#include <stdio.h>


int main(void)
{
    const char *s = "aba";
    int seen[256] = {0}, choices = 0;
    for (int i = 0; s[i]; i++) {
        unsigned char c = (unsigned char)s[i];
        if (!seen[c]) {
            seen[c] = 1;
            choices++;
        }
    }
    printf("%d\n", choices);
    return 0;
}
